class GameSettings{updateBotRatio(n,t,i){var u="#bot_number_"+t,f=parseInt(r*i/100),r=parseInt($(n).val()),f=parseInt(r*i/100),e="("+f+" bot(s))";$(u).text(e)}startMonitor(n){var t={method:"POST",body:JSON.stringify({userAgent:navigator.userAgent}),headers:{"Content-type":"application/json; charset=UTF-8"}};fetch("/jwt",t).then(n=>n.json()).then(()=>{window.open(`/game-admin/monitor.html?game=${n}`,"_blank","width=1020,height=765")})}}let gameSettings=new GameSettings;